const REQUEST_NOTE='Valores e pagamento são combinados entre vocês. O Bivaque não intermedeia pagamento nem garante o serviço.';
function requestRow(r){const st=requestStatus(r),n=requestLiveProposals(r).length;return `<button type="button" class="list-row" data-action="open-request" data-value="${r.id}">${icon('build')}<span class="txt grow"><b>${esc(requestTitle(r))}${hoodShown(r)?' · '+esc(r.hood):''}</b><small>${esc(requestStatusLabel(r))}${r.mine&&st!=='cancelled'?` · ${n} proposta${n===1?'':'s'}`:''}</small></span>${icon('chevron_right')}</button>`;}
function renderRequests(){
 const mine=requestList().filter(r=>r.mine&&r.status!=='removed').sort((a,b)=>b.createdAt-a.createdAt),forMe=providerRequests();
 return `<div class="page-head"><div><h1>Pedidos de serviço</h1><p>Descreva o que precisa e receba até ${REQUEST_LIMIT} propostas de empresas do ramo em ${esc(state.homeCity)}.</p><p class="form-note">${REQUEST_NOTE}</p></div>${!readonly()?btn('Contratar serviço','create-request','','filled','build'):''}</div>${readonlyHtml()}
 <section class="section">${sectionTitle('Meus pedidos')}${mine.length?`<div class="list">${mine.map(requestRow).join('')}</div>`:empty('Nenhum pedido ainda','Conte o serviço, o bairro e quando precisa. Empresas do ramo respondem com valor, data e prazo.','build')}</section>
 ${state.myBiz?.live?`<section class="section">${sectionTitle(`Pedidos para ${state.myBiz.name}`)}${forMe.length?`<div class="list">${forMe.map(requestRow).join('')}</div>`:empty('Nenhum pedido no seu ramo agora',`Pedidos de ${state.myBiz.cat} em ${state.myBiz.city} que atendem seus bairros aparecem aqui.`,'inbox')}</section>`:''}`;
}
function proposalCard(r,p,{showChoose,mineView}){const b=bizById(p.bizId)||(state.myBiz?.id===p.bizId?state.myBiz:null);const chosen=r.chosen===p.id;return `<article class="photo-card" style="padding:16px;display:grid;gap:8px${chosen?';border-color:var(--md-sys-color-primary)':''}"><div class="row between"><b>${esc(b?.name||'Empresa')}</b>${chosen?pill('Escolhida','ok','check_circle'):p.status==='declined'?pill('Não escolhida'):p.status==='sent'&&proposalExpired(p)?pill('Vencida','warn'):''}</div><p style="font-size:22px;font-weight:600;margin:0">${esc(proposalPrice(p))}</p><p class="small muted" style="margin:0">Disponível em ${esc(dateLabel(p.date))} · Execução: ${esc(p.duration)} · Válida até ${esc(dateLabel(p.validUntil))}</p>${p.msg?`<p class="small" style="margin:0">${esc(p.msg)}</p>`:''}<div class="row" style="gap:8px;flex-wrap:wrap">${showChoose?btn('Escolher esta proposta','choose-proposal',`${r.id}|${p.id}`,'filled','check'):''}${chosen&&r.threadId?btn('Abrir conversa','open-thread',r.threadId,'tonal','chat_bubble'):''}${mineView&&requestActive(r)?btn('Editar proposta','propose',r.id,'outlined','edit')+btn('Retirar','withdraw-proposal',r.id,'text','undo'):''}${b&&!mineView?btn('Ver empresa','open-biz',b.id,'text','storefront'):''}${mineView?'':btn('Denunciar','report',`proposal|${p.id}`,'text','flag')}</div></article>`;}
function renderRequest(){
 const r=requestById(route.id);if(r?.status==='removed')return removedContent('request');if(!r||(!r.mine&&!providerCanSee(r)))return unavailable();const details=r.mine||providerSeesDetails(r);
 const st=requestStatus(r),live=requestLiveProposals(r),active=requestActive(r);
 const head=`<div class="detail-title"><span>${pill(requestStatusLabel(r),st==='chosen'||st==='done'?'ok':st==='cancelled'||st==='expired'?'warn':'')}</span><h1>${esc(requestTitle(r))}</h1><p class="muted">${r.spec?`${esc(r.cat)} · `:''}${hoodTag(r)}${esc(requestWhenLabel(r))}${r.mine||!details?'':` · Pedido de ${esc(r.who)}`}</p></div>${details?`<p class="detail-copy">${esc(r.desc)}</p>`:'<p class="small muted">Este pedido foi encerrado. Os detalhes ficam visíveis só para a empresa escolhida.</p>'}${details&&r.photos.length?`<div class="photo-previews">${r.photos.map(src=>`<img src="${esc(src)}" alt="Foto do pedido" style="width:96px;height:96px;object-fit:cover;border-radius:12px">`).join('')}</div>`:''}<p class="form-note">${REQUEST_NOTE}</p>`;
 if(r.mine){const eligible=requestEligible(r).length;const list=st==='chosen'?[...live].sort((a,b)=>(b.id===r.chosen)-(a.id===r.chosen)):live;return `${head}${requestChosenCard(r)}<section class="section">${sectionTitle(`Propostas (${live.length} de ${REQUEST_LIMIT})`)}${live.length?proposalCompareHtml(r,list,active):''}${active&&!live.length?`<p class="small muted">Enviado para ${eligible} empresa${eligible===1?'':'s'} de ${esc(requestTitle(r))} em ${esc(r.city)}. Expira em ${esc(dateLabel(new Date(r.expiresAt).toISOString().slice(0,10)))}.</p>`:''}${live.length?'':`<div class="stack">${empty(active?'Aguardando propostas':'Nenhuma proposta recebida',active?'As empresas do ramo podem responder em até 7 dias.':'Este pedido não recebeu propostas.','request_quote')}</div>`}</section>${active?`<section class="section">${btn('Cancelar pedido','cancel-request',r.id,'outlined','close').replace('<md-outlined-button','<md-outlined-button class="danger"')}</section>`:''}`;}
 const mineP=myProposal(r);
 return `${head}<section class="section">${sectionTitle('Sua proposta')}${mineP?proposalCard(r,mineP,{mineView:true}):r.chosen?'<p class="small muted">O cliente já escolheu uma proposta.</p>':!active?'<p class="small muted">Este pedido não recebe mais propostas.</p>':requestFull(r)?`<p class="small muted">Este pedido já recebeu ${REQUEST_LIMIT} propostas.</p>`:`<p class="small muted">Você não vê as propostas de outras empresas.</p>${btn('Enviar proposta','propose',r.id,'filled','request_quote')}`}</section>${details?`<section class="section">${btn('Denunciar pedido','report',`request|${r.id}`,'text','flag')}</section>`:''}`;
}
// Rodada 58: depois da escolha, o cliente conclui o serviço, conversa com o prestador ou desiste.
function requestChosenCard(r){
 const p=r.proposals.find(x=>x.id===r.chosen);if(!p||!['chosen','done'].includes(r.status))return '';const b=bizById(p.bizId),done=r.status==='done';
 return `<section class="section"><article class="photo-card" style="padding:16px;display:grid;gap:12px;max-width:480px"><div class="row" style="gap:12px"><span class="avatar" aria-hidden="true">${esc(initals(b?.name||'Empresa'))}</span><div class="grow"><b>${esc(b?.name||'Empresa')}</b><p class="small muted" style="margin:0">${esc(proposalPrice(p))} · ${esc(p.duration)}</p></div></div>${done?`<p class="small muted" style="margin:0">Serviço concluído em ${esc(new Date(r.doneAt||Date.now()).toLocaleDateString('pt-BR'))}.</p>`:btn('Serviço concluído','complete-request',r.id,'filled','check_circle')}${btn('Conversar com o prestador','chat-provider',r.id,'outlined','chat_bubble')}${done?'':btn('Desistir desta proposta','give-up-proposal',r.id,'text','undo').replace('<md-text-button','<md-text-button class="danger"')}</article>${done?'':'<p class="form-note">Desistir reabre o pedido para as outras propostas que ainda estão válidas.</p>'}</section>`;
}
function openRequestEditor(){if(!canPost())return;if(requestList().filter(r=>r.mine&&requestActive(r)).length>=REQUEST_OPEN_MAX){notify(`Você já tem ${REQUEST_OPEN_MAX} pedidos abertos. Encerre ou cancele um antes.`,'info');return;}editor={kind:'request',photos:[],maxPhotos:REQUEST_PHOTOS};editorDirty=false;showDialog('Contratar serviço',`<p class="form-note">Seu pedido vai para as empresas do ramo em ${esc(state.homeCity)}. Até ${REQUEST_LIMIT} podem enviar proposta com valor, data e prazo.</p><div class="form-grid">${selectField('request-cat','Tipo de serviço',[['','Escolher'],...GROUP_NAMES],'','required class="full"')}<div class="full" id="request-spec-wrap"></div>${cityHasHoods(state.homeCity)?selectField('request-hood','Bairro',HOODS,'','required class="full"'):field('request-hood','Bairro (opcional)','','maxlength="60" class="full"')}${field('request-desc','O que você precisa','','type="textarea" rows="4" required minlength="20" maxlength="1000" supporting-text="Detalhe o serviço. Não informe endereço, documentos ou telefone." class="full"')}${selectField('request-when','Quando',[['asap','O quanto antes'],['until','Até uma data'],['on','Em uma data específica']],'asap','class="full"')}<label class="field-label full" id="request-date-wrap" style="display:none">Data<input type="date" id="request-date" min="${dateISO()}" value="${dateISO(3)}"></label></div>${photoUploadHtml(REQUEST_PHOTOS)}<p class="form-note">Fotos ajudam no orçamento. Evite pessoas, documentos e o número da casa. Só as empresas do ramo veem.</p><p class="form-note">${REQUEST_NOTE}</p>`,`${btn('Cancelar','close-dialog','','text')}${btn('Enviar pedido','submit-request','','filled','send')}`,'editor');$('#request-cat')?.addEventListener('change',e=>{$('#request-spec-wrap').innerHTML=specField('request-spec',e.target.value,'');});$('#request-when')?.addEventListener('change',e=>{$('#request-date-wrap').style.display=e.target.value==='asap'?'none':'';});}
function openProposalEditor(rid){const r=requestById(rid);if(!r||!state.myBiz?.live||!requestActive(r))return;const p=myProposal(r);if(!p&&requestFull(r)){notify(`Este pedido já recebeu ${REQUEST_LIMIT} propostas.`,'info');return;}editor={kind:'proposal',id:rid,photos:[]};editorDirty=false;const kind=p?.price.kind||'fixed';showDialog(p?'Editar proposta':'Enviar proposta',`<p class="form-note">${esc(requestTitle(r))} · ${esc(r.hood)} · ${esc(requestWhenLabel(r))}</p><div class="form-grid">${selectField('prop-kind','Valor',[['fixed','Valor fixo'],['range','Faixa de valor'],['visit','A combinar após visita']],kind,'class="full"')}<div data-price="fixed">${field('prop-value','Valor (R$)',p?.price.kind==='fixed'?p.price.min:'','type="number" min="1" max="1000000"')}</div><div data-price="range">${field('prop-min','De (R$)',p?.price.kind==='range'?p.price.min:'','type="number" min="1" max="1000000"')}</div><div data-price="range">${field('prop-max','Até (R$)',p?.price.kind==='range'?p.price.max:'','type="number" min="1" max="1000000"')}</div><label class="field-label">Disponível a partir de<input type="date" id="prop-date" min="${dateISO()}" value="${p?.date||dateISO(2)}"></label><label class="field-label">Proposta válida até<input type="date" id="prop-valid" min="${dateISO()}" value="${p?.validUntil||dateISO(7)}"></label>${field('prop-duration','Prazo de execução',p?.duration||'','required maxlength="40" supporting-text="Ex.: 1 dia, 2 a 3 dias" class="full"')}${field('prop-msg','Mensagem para o cliente',p?.msg||'','type="textarea" rows="3" required minlength="10" maxlength="400" class="full"')}</div><p class="form-note">${REQUEST_NOTE}</p>`,`${btn('Cancelar','close-dialog','','text')}${btn(p?'Salvar proposta':'Enviar proposta','submit-proposal',rid,'filled','send')}`,'editor');const toggle=v=>{for(const el of dialog.querySelectorAll('[data-price]'))el.style.display=el.dataset.price===v?'':'none';};toggle(kind);$('#prop-kind')?.addEventListener('change',e=>toggle(e.target.value));}
// Rodada 16: propostas lado a lado, com as mesmas linhas alinhadas (valor, data, execução,
// validade, mensagem) e destaques de menor valor e data mais cedo. A ordem padrão é a de
// chegada (ADR-20261015, P6: sem ranking pago); a pessoa pode reordenar.
let proposalSort={rid:null,sort:'arrival'};
const proposalSortFor=r=>proposalSort.rid===r.id?proposalSort.sort:'arrival';
const PROPOSAL_SORTS=[['arrival','Chegada'],['price','Menor valor'],['date','Mais cedo']];
function proposalSorted(r,list){const sort=proposalSortFor(r),base=v=>v.price.kind==='visit'?Infinity:v.price.min;return sort==='price'?[...list].sort((a,b)=>base(a)-base(b)):sort==='date'?[...list].sort((a,b)=>a.date.localeCompare(b.date)):list;}
function proposalCompareHtml(r,list,active){
 const open=list.filter(p=>p.status==='sent'&&!proposalExpired(p)),priced=open.filter(p=>p.price.kind!=='visit'),mins=priced.map(p=>p.price.min),dates=open.map(p=>p.date).sort(),low=priced.length>1&&Math.min(...mins)<Math.max(...mins)?Math.min(...mins):null,early=dates.length>1&&dates[0]<dates.at(-1)?dates[0]:null;
 const sort=active&&list.length>1?`<div class="prop-sort" role="group" aria-label="Ordenar propostas"><span class="small muted">Ordenar por</span><md-chip-set>${PROPOSAL_SORTS.map(([v,label])=>`<md-filter-chip label="${label}" ${proposalSortFor(r)===v?'selected':''} data-action="proposal-sort" data-value="${v}"></md-filter-chip>`).join('')}</md-chip-set></div>`:'';
 const col=p=>{const b=bizById(p.bizId),chosen=r.chosen===p.id,badges=[low!==null&&p.price.kind!=='visit'&&p.price.min===low?`<span class="prop-badge">${icon('sell')}Menor valor</span>`:'',early&&p.date===early?`<span class="prop-badge">${icon('bolt')}Mais cedo</span>`:'',chosen?pill('Escolhida','ok','check_circle'):p.status==='declined'?(active&&proposalExpired(p)?pill('Vencida','warn'):pill('Não escolhida')):p.status==='sent'&&proposalExpired(p)?pill('Vencida','warn'):''].join('');
  return `<article class="prop-col${chosen?' is-chosen':''}${p.status==='declined'||p.status==='sent'&&proposalExpired(p)?' is-declined':''}" aria-labelledby="prop-name-${p.id}"><header><b id="prop-name-${p.id}">${esc(b?.name||'Empresa')}</b><small>${b?.recN?`${b.recN} ${b.recN===1?'indicação':'indicações'}`:'Empresa do ramo'}</small></header><div class="prop-badges">${badges}</div><p class="prop-price">${esc(proposalPrice(p))}</p><dl class="prop-facts"><div><dt>${icon('event')}Disponível</dt><dd>${esc(dateLabel(p.date))}</dd></div><div><dt>${icon('timer')}Execução</dt><dd>${esc(p.duration)}</dd></div><div><dt>${icon('hourglass_top')}Válida até</dt><dd>${esc(dateLabel(p.validUntil))}</dd></div></dl><p class="prop-msg">${esc(p.msg||'')}</p><div class="prop-actions">${active&&!proposalExpired(p)?btn('Escolher','choose-proposal',`${r.id}|${p.id}`,'filled','check').replace('<md-filled-button',`<md-filled-button aria-label="Escolher a proposta de ${esc(b?.name||'Empresa')}"`):''}${chosen&&r.threadId?btn('Abrir conversa','open-thread',r.threadId,'tonal','chat_bubble'):''}<div class="row">${b?btn('Ver empresa','open-biz',b.id,'text','storefront'):''}${btn('Denunciar','report',`proposal|${p.id}`,'text','flag').replace('<md-text-button',`<md-text-button aria-label="Denunciar a proposta de ${esc(b?.name||'Empresa')}"`)}</div></div></article>`;};
 return `${sort}<div class="prop-compare" role="region" aria-label="Propostas lado a lado" tabindex="0">${(active?proposalSorted(r,list):list).map(col).join('')}</div>`;
}
